From a1c71140b94c85caaf081a50efcb349aff0e1241 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:49:12 +0100
Subject: [PATCH] plasma-apply-colorscheme: switch to a custom accent color
 with -a

Passing an accent color only tinted the palette and left the accent mode
alone, so it showed as "from wallpaper" or "from color scheme" and got
replaced on the next wallpaper or scheme change. Now it saves the color.

BUG: 472792
---
 kcms/colors/plasma-apply-colorscheme.cpp | 4 ++++
 1 file changed, 4 insertions(+)

diff --git a/kcms/colors/plasma-apply-colorscheme.cpp b/kcms/colors/plasma-apply-colorscheme.cpp
index 3709618e81..526e358b47 100644
--- a/kcms/colors/plasma-apply-colorscheme.cpp
+++ b/kcms/colors/plasma-apply-colorscheme.cpp
@@ -144,7 +144,11 @@ int main(int argc, char **argv)
             // animation start event before we potentially trigger client side changes
             QDBusConnection::sessionBus().call(msg);

+            settings->setAccentColor(QColor(accentColor));
+            settings->setLastUsedCustomAccentColor(QColor(accentColor));
+            settings->setAccentColorFromWallpaper(false);
             applyScheme(path, settings->config(), KConfig::Notify, {accentColor});
+            settings->save();
             notifyKcmChange(GlobalChangeType::PaletteChanged);

             ts << i18n("Successfully applied the accent color %1", accentColor) << Qt::endl;
-- 
